                  info_es: '<b>Razón Corriente = Activos Corrientes / Pasivos Corrientes</b><br><br>Activos Corrientes: $42,100<br>Pasivos Corrientes: Cuentas por Pagar ($12,000) + Préstamo Bancario ($10,000) = $22,000<br><br>Divida activos corrientes entre pasivos corrientes y redondee a 2 decimales.' }
            ];
        }

        // Resolve the active language, preferring the framework i18n module so that the
        // dynamic content (events, analysis, briefing) always matches the static UI and
        // follows runtime language switches. Falls back to <html lang>, then 'en'.
        _getLang() {
            try {
                if (window.vcI18n && window.vcI18n._lang) {
                    return String(window.vcI18n._lang).toLowerCase().indexOf('es') === 0 ? 'es' : 'en';
                }
            } catch (e) {}
            try {
                if (window.mySimulation && window.mySimulation.currentLanguage) {
                    return String(window.mySimulation.currentLanguage).toLowerCase().indexOf('es') === 0 ? 'es' : 'en';
                }
            } catch (e) {}
            var html = document.documentElement;
            if (html && html.lang && html.lang.toLowerCase().indexOf('es') === 0) return 'es';
            return 'en';
        }

        _t() {
            return (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function(k) { return k; };
        }

        _populateDropdowns() {
            var lang = this._getLang();
            var debitSel = document.getElementById('debitAccount');
            var creditSel = document.getElementById('creditAccount');
            if (!debitSel || !creditSel) return;

            var placeholder = lang === 'es' ? '-- Seleccione una cuenta --' : '-- Select an account --';
            var html = '<option value="">' + placeholder + '</option>';
            for (var i = 0; i < this.ACCOUNTS.length; i++) {
                var a = this.ACCOUNTS[i];
                var name = lang === 'es' ? a.es : a.en;
                html += '<option value="' + a.key + '">' + a.code + ' - ' + name + '</option>';
            }
            debitSel.innerHTML = html;
            creditSel.innerHTML = html;
        }

        _updateBriefing(state) {
            var period = (state && state.currentPeriod) || 1;
            var lang = this._getLang();
            var phaseEl = document.getElementById('phaseTitle');
            var briefEl = document.getElementById('briefingText');
            var journalPanel = document.getElementById('journalPanel');
            var analysisPanel = document.getElementById('analysisPanel');

            if (period <= 18) {
                var idx = Math.min(period - 1, this.EVENTS.length - 1);
                var evt = this.EVENTS[idx];
                if (phaseEl) {
                    phaseEl.textContent = lang === 'es'
                        ? 'Fase 1: Asientos Contables — Evento ' + period + ' de 18'
                        : 'Phase 1: Journal Entries — Event ' + period + ' of 18';
                }
                if (briefEl) {
                    var dayLabel = lang === 'es' ? 'Mes 1, Día ' : 'Month 1, Day ';
                    briefEl.innerHTML = '<strong>' + dayLabel + evt.day + '</strong><br>' + (lang === 'es' ? evt.es : evt.en);
                }
                if (journalPanel) journalPanel.style.display = 'block';
                if (analysisPanel) analysisPanel.style.display = 'none';
                this._populateDropdowns();
            } else {
                var aIdx = Math.min(period - 19, this.ANALYSIS.length - 1);
                var task = this.ANALYSIS[aIdx];
                if (phaseEl) phaseEl.textContent = lang === 'es' ? task.heading_es : task.heading_en;
                if (briefEl) briefEl.innerHTML = '';
                if (journalPanel) journalPanel.style.display = 'none';
                if (analysisPanel) analysisPanel.style.display = 'block';

                var heading = document.getElementById('analysisHeading');
                if (heading) heading.textContent = lang === 'es' ? task.heading_es : task.heading_en;
                var info = document.getElementById('analysisInfo');
                if (info) info.innerHTML = lang === 'es' ? task.info_es : task.info_en;
                var label = document.getElementById('analysisLabel');
                if (label) label.textContent = lang === 'es' ? task.label_es : task.label_en;
                var input = document.getElementById('analysisInput');
                if (input) input.value = '';
            }

            var feedback = document.getElementById('feedbackArea');
            if (feedback) feedback.innerHTML = '';
        }

        initialize(state) {
            // Reset on a fresh start OR when history is empty (undo back to the beginning).
            // The framework calls initialize() again after undoLastPeriod() pops the last
            // history entry; keying the reset on history (not on a non-empty domainState)
            // ensures a replay starts from zero instead of double-counting the score.
            // Resume mid-game (history present) keeps the loaded domainState untouched.
            var ds = state.domainState;
            var needsReset = !ds || Object.keys(ds).length === 0 || !state.history || state.history.length === 0;
            if (needsReset) {
                state.domainState = {
                    score: 0,
                    totalCorrect: 0,
                    totalAttempts: 0,
                    currentAttempts: 0,
                    scoreHistory: [],
                    performance: { overallScore: 0, grade: 'F', tier: 'tier_beginner', insights: [] }
                };
            } else if (!state.domainState.performance) {
                // Resumed from a pre-1.1.0 save that predates the grade block — make sure
                // the key the grading layer reads always exists.
                state.domainState.performance = { overallScore: 0, grade: 'F', tier: 'tier_beginner', insights: [] };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    debitAccount: '',
                    creditAccount: '',
                    debitAmount: 0,
                    creditAmount: 0,
                    analysisAnswer: 0
                };
            }
            this._updateBriefing(state);
        }

        _countAttempt(state) {
            state.domainState.currentAttempts = (state.domainState.currentAttempts || 0) + 1;
            state.domainState.totalAttempts = (state.domainState.totalAttempts || 0) + 1;
            var attemptsEl = document.getElementById('attemptsDisplay');
            if (attemptsEl) attemptsEl.textContent = state.domainState.totalAttempts;
        }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            var period = state.currentPeriod || 1;
            var lang = this._getLang();
            var feedback = document.getElementById('feedbackArea');

            if (period <= 18) {
                var debitSel = document.getElementById('debitAccount');
                var creditSel = document.getElementById('creditAccount');
                var debitAmt = document.getElementById('debitAmount');
                var creditAmt = document.getElementById('creditAmount');

                decisions.debitAccount = debitSel ? debitSel.value : '';
                decisions.creditAccount = creditSel ? creditSel.value : '';
                decisions.debitAmount = debitAmt ? parseFloat(debitAmt.value) || 0 : 0;
                decisions.creditAmount = creditAmt ? parseFloat(creditAmt.value) || 0 : 0;

                // Presence checks first: an incomplete form is not a scored attempt.
                if (!decisions.debitAccount || !decisions.creditAccount) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('select_accounts_warning'), 'warning');
                    return false;
                }
                if (decisions.debitAmount <= 0 || decisions.creditAmount <= 0) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('enter_amounts_warning'), 'warning');
                    return false;
                }

                // From here on it is a genuine attempt — count it once.
                this._countAttempt(state);

                var evt = this.EVENTS[period - 1];

                if (Math.abs(decisions.debitAmount - decisions.creditAmount) > 0.01) {
                    if (feedback) feedback.innerHTML = '<span class="acctgame-wrong">' +
                        (lang === 'es'
                            ? '✗ Los débitos ($' + decisions.debitAmount.toFixed(2) + ') no son iguales a los créditos ($' + decisions.creditAmount.toFixed(2) + '). Recuerde: débitos deben ser iguales a créditos.'
                            : '✗ Debits ($' + decisions.debitAmount.toFixed(2) + ') do not equal credits ($' + decisions.creditAmount.toFixed(2) + '). Remember: debits must equal credits.')
                        + '</span>';
                    return false;
                }

                var errors = [];
                if (decisions.debitAccount !== evt.debit) {
                    errors.push(lang === 'es'
                        ? 'La cuenta de débito es incorrecta. Piense: esta transacción aumenta un activo o un gasto?'
                        : 'The debit account is incorrect. Think: does this transaction increase an asset or an expense?');
                }
                if (decisions.creditAccount !== evt.credit) {
                    errors.push(lang === 'es'
                        ? 'La cuenta de crédito es incorrecta. Piense: aumenta un pasivo, capital o ingreso?'
                        : 'The credit account is incorrect. Think: does it increase a liability, equity, or revenue?');
                }
                if (Math.abs(decisions.debitAmount - evt.amount) > 0.01) {
                    errors.push(lang === 'es'
                        ? 'El monto no es correcto. Revise la descripción del evento.'
                        : 'The amount is not correct. Review the event description.');
                }

                if (errors.length > 0) {
                    if (state.domainState.currentAttempts >= 3) {
                        var hint = lang === 'es'
                            ? '<br><em>Pista: Débito = ' + this._acctName(evt.debit, lang) + ', Crédito = ' + this._acctName(evt.credit, lang) + ', Monto = $' + evt.amount.toFixed(2) + '</em>'
                            : '<br><em>Hint: Debit = ' + this._acctName(evt.debit, lang) + ', Credit = ' + this._acctName(evt.credit, lang) + ', Amount = $' + evt.amount.toFixed(2) + '</em>';
                        errors.push(hint);
                    }
                    if (feedback) feedback.innerHTML = '<span class="acctgame-wrong">✗ ' + errors.join('<br>') + '</span>';
                    return false;
                }

                if (feedback) feedback.innerHTML = '<span class="acctgame-correct">✓ ' +
                    (lang === 'es' ? 'Correcto!' : 'Correct!') + '</span>';
                return true;

            } else {
                var input = document.getElementById('analysisInput');
                decisions.analysisAnswer = input ? parseFloat(input.value) || 0 : 0;

                if (decisions.analysisAnswer <= 0) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('enter_answer_warning'), 'warning');
                    return false;
                }

                // Genuine attempt — count it once.
                this._countAttempt(state);

                var aIdx = period - 19;
                var task = this.ANALYSIS[aIdx];
                if (Math.abs(decisions.analysisAnswer - task.answer) > task.tolerance) {
                    var msg = lang === 'es'
                        ? '✗ Respuesta incorrecta. Revise los datos e intente de nuevo.'
                        : '✗ Incorrect answer. Review the data and try again.';
                    if (state.domainState.currentAttempts >= 3) {
                        msg += lang === 'es'
                            ? '<br><em>Pista: La respuesta correcta es $' + task.answer.toFixed(2) + '</em>'
                            : '<br><em>Hint: The correct answer is $' + task.answer.toFixed(2) + '</em>';
                    }
                    if (feedback) feedback.innerHTML = '<span class="acctgame-wrong">' + msg + '</span>';
                    return false;
                }

                if (feedback) feedback.innerHTML = '<span class="acctgame-correct">✓ ' +
                    (lang === 'es' ? 'Correcto!' : 'Correct!') + '</span>';
                return true;
            }
        }

        _acctName(key, lang) {
            for (var i = 0; i < this.ACCOUNTS.length; i++) {
                if (this.ACCOUNTS[i].key === key) return lang === 'es' ? this.ACCOUNTS[i].es : this.ACCOUNTS[i].en;
            }
            return key;
        }

        calculateResults(state) {
            var period = state.currentPeriod;
            var attempts = state.domainState.currentAttempts || 1;
            var points = 0;
            if (attempts === 1) points = 3;
            else if (attempts === 2) points = 2;
            else if (attempts === 3) points = 1;

            state.domainState.score += points;
            state.domainState.totalCorrect += 1;
            state.domainState.scoreHistory.push(state.domainState.score);
            state.domainState.currentAttempts = 0;

            // --- Grade contract (fixes the always-0 gradebook) ---
            // express/results_utils.php :: express_extractMetrics reads the score ONLY from
            // domainState.performance.overallScore (and the letter from .grade); without this
            // block express_compute_grade records 0.0/100 for every student. overallScore is
            // the cumulative points expressed as a percentage of the maximum (22*3 = 66) — a
            // mirror of the on-screen Score, not a new scoring rule. Written every period so
            // it is captured by addToHistory() (per-period analytics) and by the final
            // PERIOD_END persist (the recorded grade).
            var maxPoints = 22 * 3;
            var overall = Math.max(0, Math.min(100, Math.round((state.domainState.score / maxPoints) * 100)));
            state.domainState.performance = {
                overallScore: overall,
                grade: this._gradeLetter(overall),
                tier: this._perfTierKey(overall),
                insights: []
            };

            var lang = this._getLang();
            var taskDesc = '';
            if (period <= 18) {
                var evt = this.EVENTS[period - 1];
                taskDesc = (lang === 'es' ? 'Día ' : 'Day ') + evt.day;
            } else {
                var aIdx = period - 19;
                var task = this.ANALYSIS[aIdx];
                taskDesc = lang === 'es' ? task.heading_es : task.heading_en;
            }

            // The briefing/journal panel for the next period is refreshed by the framework's
            // 'period:submitted' event (subscribed in setupUI), which fires AFTER the engine
            // increments currentPeriod — so the shown task always matches the graded task.
            // (The previous setTimeout(..., 500) read the already-incremented currentPeriod
            // and added +1, overshooting by one and desyncing the briefing from grading.)

            return {
                period: period,
                phase: period <= 18 ? 1 : this.ANALYSIS[Math.min(period - 19, 3)].phase,
                taskDesc: taskDesc,
                attempts: attempts,
                points: points,
                cumulativeScore: state.domainState.score,
                correct: state.domainState.totalCorrect
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.score');
            uiManager.bind('correctDisplay', 'domainState.totalCorrect', function(v) { return v + ' / 22'; });
            uiManager.bind('attemptsDisplay', 'domainState.totalAttempts');
            uiManager.bind('phaseDisplay', 'currentPeriod', function(v) {
                if (v <= 18) return '1';
                if (v === 19) return '2';
                if (v <= 21) return '3';
                return '4';
            });

            var self = this;
            var fw = window.mySimulation;
            // Drive the briefing off framework events instead of a timer (see calculateResults).
            if (fw && fw.eventBus && typeof fw.eventBus.on === 'function') {
                fw.eventBus.on('period:submitted', function() { try { self._updateBriefing(fw.state); } catch (e) {} });
                fw.eventBus.on('period:undone', function() { try { self._updateBriefing(fw.state); } catch (e) {} });
            }
            if (typeof document !== 'undefined' && document.addEventListener) {
                document.addEventListener('express:langchanged', function() {
                    try {
                        if (window.mySimulation) self._updateBriefing(window.mySimulation.state);
                        self._applyAriaLabels();
                    } catch (e) {}
                });
            }
            this._applyAriaLabels();
        }

        _applyAriaLabels() {
            var t = this._t();
            try {
                var c = document.getElementById('scoreChart');
                if (c) c.setAttribute('aria-label', t('chart_aria'));
                var sc = document.querySelector('.acctgame-sim-status-cards');
                if (sc) sc.setAttribute('aria-label', t('status_region'));
                var bc = document.getElementById('briefingCard');
                if (bc) bc.setAttribute('aria-label', t('briefing_region'));
            } catch (e) {}
        }

        getChartConfig() {
            var t = this._t();
            return {
                scoreChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: t('chart_series'),
                            data: [],
                            borderColor: '#27ae60',
                            backgroundColor: 'rgba(39,174,96,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: t('chart_title') } },
                        scales: { y: { beginAtZero: true } }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.scoreHistory.map(function(_, i) { return 'P' + (i + 1); });
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.scoreHistory }]
                }
            };
        }

        getPerformanceSummary(history) {
            var t = this._t();
            if (!history || !history.length) {
                return { totalPeriods: 0, message: t('insight_beginner'), insights: [] };
            }
            var totalPoints = 0;
            var totalAttempts = 0;
            for (var i = 0; i < history.length; i++) {
                totalPoints += (history[i].results && history[i].results.points) || 0;
                totalAttempts += (history[i].results && history[i].results.attempts) || 0;
            }
            var maxPoints = 22 * 3;
            var pct = maxPoints ? Math.round((totalPoints / maxPoints) * 100) : 0;
            var tierKey = this._perfTierKey(pct);
            var insightKey = this._insightKey(pct);

            return {
                totalPeriods: history.length,
                totalPoints: totalPoints,
                maxPoints: maxPoints,
                percentage: pct,
                overallScore: pct,
                totalCorrect: history.length,
                totalAttempts: totalAttempts,
                performance: t(tierKey),
                tier: tierKey,
                grade: this._gradeLetter(pct),
                message: t(insightKey),
                insights: [ t(insightKey) ],
                grossProfitMargin: '49.0%',
                netProfitMargin: '0.81%',
                currentRatio: '1.91',
                debtToEquity: '0.88'
            };
        }

        _gradeLetter(score) {
            if (score >= 85) return 'A';
            if (score >= 70) return 'B';
            if (score >= 55) return 'C';
            if (score >= 40) return 'D';
            return 'F';
        }

        _perfTierKey(score) {
            if (score >= 80) return 'tier_excellent';
            if (score >= 60) return 'tier_good';
            if (score >= 40) return 'tier_intermediate';
            return 'tier_beginner';
        }

        _insightKey(score) {
            if (score >= 80) return 'insight_excellent';
            if (score >= 60) return 'insight_good';
            return 'insight_beginner';
        }

        formatCompletionMessage(summary) {
            var t = this._t();
            summary = summary || {};
            var pct = Math.round(summary.percentage != null ? summary.percentage : (summary.overallScore || 0));
            var grade = summary.grade || this._gradeLetter(pct);
            var tier = summary.performance || t(this._perfTierKey(pct));
            var insights = summary.insights && summary.insights.length ? summary.insights : [ t(this._insightKey(pct)) ];

            var lis = '';
            for (var i = 0; i < insights.length; i++) { lis += '<li>' + insights[i] + '</li>'; }

            function ratio(labelKey, value) {
                return '<div class="acctgame-sim-completion-ratio">' +
                    '<span class="acctgame-ratio-label">' + t(labelKey) + '</span>' +
                    '<span class="acctgame-ratio-value">' + value + '</span></div>';
            }
            var ratios =
                ratio('ratio_gross_margin', summary.grossProfitMargin || '49.0%') +
                ratio('ratio_net_margin', summary.netProfitMargin || '0.81%') +
                ratio('ratio_current', summary.currentRatio || '1.91') +
                ratio('ratio_debt_equity', summary.debtToEquity || '0.88');

            return '' +
                '<div class="acctgame-sim-completion">' +
                    '<h3>' + t('completion_heading') + '</h3>' +
                    '<div class="acctgame-sim-completion-grade" role="img" aria-label="' + t('completion_grade_aria') + ' ' + grade + '">' + grade + '</div>' +
                    '<p class="acctgame-sim-completion-score">' + t('completion_score_label') + ': <strong>' + pct + '/100</strong></p>' +
                    '<p class="acctgame-sim-completion-tier">' + tier + '</p>' +
                    (lis ? '<ul class="acctgame-sim-completion-insights">' + lis + '</ul>' : '') +
                    '<p class="acctgame-sim-completion-ratios-heading"><strong>' + t('ratios_heading') + '</strong></p>' +
                    '<div class="acctgame-sim-completion-ratios">' + ratios + '</div>' +
                '</div>';
        }

        getHint(state, results) {
            var lang = this._getLang();
            var period = state.currentPeriod;
            if (period <= 18) {
                return lang === 'es'
                    ? 'Recuerde: débitos van a la izquierda de la cuenta T, créditos a la derecha. Los activos y gastos aumentan con débitos.'
                    : 'Remember: debits go on the left side of the T-account, credits on the right. Assets and expenses increase with debits.';
            }
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.taskDesc', label: 'Task', i18nKey: 'col_task' },
